<label class="opcion"> <input type="radio" name="g4q2" value="A" /> A. n = 8 </label> <label class="opcion"> <input type="radio" name="g4q2" value="B" /> B. n = 11 </label> <label class="opcion"> <input type="radio" name="g4q2" value="C" /> C. n = 14 </label> <label class="opcion"> <input type="radio" name="g4q2" value="D" /> D. n = 5 </label> <button type="button" data-question="g4q2"> Revisar respuesta </button>
