        }

      };

      const botones = root.querySelectorAll('button[data-question]');

      botones.forEach(function (boton) {

        boton.addEventListener('click', function () {

          const pregunta = boton.getAttribute('data-question');

          const seleccion = root.querySelector(
            'input[name="' + pregunta + '"]:checked'
