          const salida = root.querySelector(
            '[data-feedback="' + pregunta + '"]'
          );

          if (!seleccion) {
            salida.textContent = 'Selecciona una opción antes de revisar.';
            return;
          }

          salida.textContent = mensajes[pregunta][seleccion.value];

        });

      });

    })();
  </script>
